#include "consumer_consumer.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void consumer_consumer_initialize(void);
void consumer_consumer_notify(microkit_channel channel);
void consumer_consumer_timeTriggered(void);

volatile sb_queue_int32_t_1_t *sample_queue_1;
sb_queue_int32_t_1_Recv_t sample_recv_queue;

#define PORT_FROM_MON 0

bool sample_is_empty(void) {
  return sb_queue_int32_t_1_is_empty(&sample_recv_queue);
}

bool get_sample_poll(sb_event_counter_t *numDropped, int32_t *data) {
  return sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &sample_recv_queue, numDropped, data);
}

bool get_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return get_sample_poll (&numDropped, data);
}

bool peek_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return sb_queue_int32_t_1_peek((sb_queue_int32_t_1_Recv_t *) &sample_recv_queue, &numDropped, data);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_int32_t_1_Recv_init(&sample_recv_queue, (sb_queue_int32_t_1_t *) sample_queue_1);

  consumer_consumer_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      consumer_consumer_timeTriggered();
      break;
    default:
      consumer_consumer_notify(channel);
  }
}
